/**
 * Get the network configuration for a given network.
 *
 * @throws {UmbraError} if the network has not been populated.
 */
export function getNetworkConfig(network: Network): NetworkConfig {
  const config = NETWORK_CONFIGS[network];
  if (config === null) {
    throw new UmbraError(
      `Network configuration for "${network}" has not been populated. ` +
        `Run the build pipeline targeting this network first.`,
      { context: { network } },
    );
  }
  return config;
}
